var findKthLargest = function(nums, k) {
    const target = nums.length - k;
    let left = 0, right = nums.length - 1;
    while (left <= right) {
        const pivotIdx = left + Math.floor(Math.random() * (right - left + 1));
        const pivot = nums[pivotIdx];
        let less = left, current = left, greater = right;
        while (current <= greater) {
            if (nums[current] < pivot) {
                [nums[less], nums[current]] = [nums[current], nums[less]];
                less++; current++;
            } else if (nums[current] > pivot) {
                [nums[current], nums[greater]] = [nums[greater], nums[current]];
                greater--;
            } else {
                current++;
            }
        }
        if (target < less) right = less - 1;
        else if (target > greater) left = greater + 1;
        else return nums[target];
    }
};

solution.python:
import random
from typing import List


class Solution:
    def findKthLargest(self, nums: List[int], k: int) -> int:
        target = len(nums) - k
        left, right = 0, len(nums) - 1

        while left <= right:
            pivot = nums[random.randint(left, right)]
            less = left
            current = left
            greater = right

            while current <= greater:
                if nums[current] < pivot:
                    nums[less], nums[current] = nums[current], nums[less]
                    less += 1
                    current += 1
                elif nums[current] > pivot:
                    nums[current], nums[greater] = nums[greater], nums[current]
                    greater -= 1
                else:
                    current += 1

            if target < less:
                right = less - 1
            elif target > greater:
                left = greater + 1
            else:
                return nums[target]

        raise ValueError("k is outside the valid range")
